package tmmodern;
import net.minecraft.core.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.minecraft.world.phys.shapes.*;import net.minecraft.util.RandomSource;import net.minecraft.server.level.ServerLevel;
public class Warpwood {
    public static class Log extends RotatedPillarBlock {
        public static final BooleanProperty KNOT=BooleanProperty.create("knot");public Log(){super(Properties.copy(Blocks.OAK_LOG).strength(2.5f));registerDefaultState(defaultBlockState().setValue(KNOT,false));}
        @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){super.createBlockStateDefinition(b);b.add(KNOT);}
        @Override public float getDestroyProgress(BlockState state,net.minecraft.world.entity.player.Player p,BlockGetter l,BlockPos pos){return super.getDestroyProgress(state,p,l,pos)/(state.getValue(KNOT)?10:1);}
        @Override public int getFlammability(BlockState s,BlockGetter l,BlockPos p,Direction face){return 0;}
        @Override public java.util.List<ItemStack> getDrops(BlockState state,net.minecraft.world.level.storage.loot.LootParams.Builder loot){if(state.getValue(KNOT))return java.util.List.of(new ItemStack(TMRuntime.item("thaumcraft:void_seed"),1+loot.getLevel().random.nextInt(5)));return java.util.List.of(new ItemStack(this));}
        @Override public void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(s.getBlock()!=next.getBlock()&&s.getValue(KNOT)){TMEffects.sparkles(l,net.minecraft.world.phys.Vec3.atCenterOf(p),15,0,1,0);TMRuntime.sound(l,p,"thaumcraft:craftfail",1,1);}super.onRemove(s,l,p,next,moving);}
    }
    public static class Leaves extends LeavesBlock {public Leaves(){super(Properties.copy(Blocks.OAK_LEAVES).strength(.1f).noOcclusion());}@Override public int getFlammability(BlockState s,BlockGetter l,BlockPos p,Direction f){return 0;}@Override public int getLightBlock(BlockState s,BlockGetter l,BlockPos p){return 0;}}
    public static class Sapling extends BushBlock implements BonemealableBlock {
        public Sapling(){super(Properties.copy(Blocks.OAK_SAPLING).randomTicks());}
        @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return Block.box(2,0,2,14,13,14);}
        @Override public void randomTick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){if(l.getMaxLocalRawBrightness(p.above())>=9&&r.nextInt(7)==0)grow(l,p,r);}
        @Override public boolean isValidBonemealTarget(LevelReader l,BlockPos p,BlockState s,boolean client){return true;}@Override public boolean isBonemealSuccess(Level l,RandomSource r,BlockPos p,BlockState s){return r.nextFloat()<.45f;}@Override public void performBonemeal(ServerLevel l,RandomSource r,BlockPos p,BlockState s){grow(l,p,r);}
    }
    public static class Nightshade extends BushBlock {public Nightshade(){super(Properties.copy(Blocks.WITHER_ROSE));}@Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return Block.box(3,0,3,13,10,13);}@Override public void entityInside(BlockState s,Level l,BlockPos p,Entity e){if(!l.isClientSide&&e instanceof LivingEntity living){living.hurt(TMRuntime.nightshade(l),1);living.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.POISON,140));}}}
    public static boolean grow(ServerLevel l,BlockPos root,RandomSource r){int height=7+r.nextInt(5);if(root.getY()+height+6>=l.getMaxBuildHeight())return false;for(int y=1;y<=height+1;y++){int spread=y>=height-1?3:1;for(var p:BlockPos.betweenClosed(root.offset(-spread,y,-spread),root.offset(spread,y,spread)))if(!l.getBlockState(p).canBeReplaced()&&!l.getBlockState(p).is(net.minecraft.tags.BlockTags.LEAVES))return false;}if(!l.getBlockState(root.below()).canSustainPlant(l,root.below(),Direction.UP,(net.minecraftforge.common.IPlantable)TaintedMagic.block("warpwood_sapling")))return false;
        var log=TaintedMagic.block("warpwood_log").defaultBlockState();var leaves=TaintedMagic.block("warpwood_leaves").defaultBlockState();int end=height+3+r.nextInt(3);for(int y=height-5;y<=end;y++){int cy=Math.max(height-3,Math.min(height,y));for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++){var p=root.offset(x,y,z);if(x*x+(y-cy)*(y-cy)+z*z<10+r.nextInt(8)&&(l.getBlockState(p).canBeReplaced()||l.getBlockState(p).is(net.minecraft.tags.BlockTags.LEAVES)))l.setBlock(p,leaves,3);}}
        int chance=height;boolean previous=false;for(int y=0;y<height;y++){boolean knot=y>0&&!previous&&r.nextInt(Math.max(1,chance))==0;l.setBlock(root.above(y),log.setValue(Log.KNOT,knot),3);if(!knot)chance--;previous=knot;for(var d:Direction.Plane.HORIZONTAL)l.setBlock(root.above(y).relative(d),log,3);}l.setBlock(root.above(height),log,3);
        for(int x:new int[]{-1,1})for(int z:new int[]{-1,1}){l.setBlock(root.offset(x,0,z),log,3);if(r.nextInt(3)!=0)l.setBlock(root.offset(x,1,z),log,3);l.setBlock(root.offset(x,height-4,z),log,3);if(r.nextInt(3)==0)l.setBlock(root.offset(x,height-5,z),log,3);}for(var d:Direction.Plane.HORIZONTAL){var horizontal=log.setValue(RotatedPillarBlock.AXIS,d.getAxis());l.setBlock(root.relative(d,2),horizontal,3);l.setBlock(root.relative(d,2).below(),log,3);l.setBlock(root.relative(d,2).above(height-4),horizontal,3);}
        for(int i=0;i<64;i++){var p=root.offset(r.nextInt(8)-r.nextInt(8),r.nextInt(4)-r.nextInt(4),r.nextInt(8)-r.nextInt(8));var state=TaintedMagic.block("nightshade_bush").defaultBlockState();if(l.isEmptyBlock(p)&&state.canSurvive(l,p))l.setBlock(p,state,3);}return true;}
}
